/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistMainForm || { elements: [] });
        scwin.setIPO();
        if (($c.util.getComponent('dma_RegisterReq').get('nowPage')) > ($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd'))) {
            return;
        }
        scwin.commaValueAll();
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05002c.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    try {
        const recentAcntgPdStrtYymm = $c.util.getComponent('dma_RegisterReq').get('recentAcntgPdStrtYymm');
        const recentAcntgPdEndYymm = $c.util.getComponent('dma_RegisterReq').get('recentAcntgPdEndYymm');
        if (recentAcntgPdStrtYymm.length !== 0) {
            $c.util.getComponent('ipt_recentAcntgPdStrtYymm1').setValue(recentAcntgPdStrtYymm.substring(0, 4));
            $c.util.getComponent('ipt_recentAcntgPdStrtYymm2').setValue(recentAcntgPdStrtYymm.substring(4));
        }
        if (recentAcntgPdEndYymm.length !== 0) {
            $c.util.getComponent('ipt_recentAcntgPdEndYymm1').setValue(recentAcntgPdEndYymm.substring(0, 4));
            $c.util.getComponent('ipt_recentAcntgPdEndYymm2').setValue(recentAcntgPdEndYymm.substring(4));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05002c.onloadDataSet" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelist.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    const invstgClmTpCd = $c.util.getComponent('dma_RegisterReq').get('invstgClmTpCd');
    if (!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) {
        return false;
    }
    if ($c.util.getComponent('ipt_fiscalyy').getValue().length !== 4) {
        await $c.win.alert("회계년도를 정확히 입력해주십시요.");
        $c.util.getComponent("ipt_fiscalyy").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
